/**
 * Proofs for the Rust printer.
 *
 * The interesting assertion is `generate`'s on a tiny synthetic corpus: it
 * pins the exact text of every construct the printer can emit, so a change in
 * layout is a visible diff here and not only in the generated file.
 *
 * @module
 */

/** @import { Data } from '../types.ts' */
import { assert, assertEq } from '../../asserts/module.f.mjs'
import { data, functionValue, ref, throws } from '../module.f.mjs'
import { call, directory, generate, path, valueExpr } from './module.f.mjs'
import { snakeCase } from '../../media/rust/module.f.mjs'

/**
 * One case of every shape the printer can emit: a shared value and a
 * reference to it, a skipped case, a throwing case, and a commutative binary
 * operator.
 *
 * @type {Data}
 */
const sample = {
    eq: {
        shared: { emptyArray: [] },
        cases: [
            { name: 'itself', a: ref('emptyArray'), b: ref('emptyArray'), eq: true },
            { name: 'skipped', a: null, b: null, eq: true, rust: 'not yet' },
        ],
    },
    groups: [
        { op: 'unaryPlus', cases: [{ name: 'bigint', args: [0n], expected: throws }] },
        {
            op: 'mul',
            commutative: true,
            cases: [{ name: 'oneByTwo', args: [1, 2], expected: 2 }],
        },
    ],
}

const expected = `// @generated by \`npm run ci-update\` from \`fjs/nanvm/module.f.mjs\`.
// Do not edit: change the shared operator test data and regenerate.

use super::harness::*;

#[rustfmt::skip]
fn eq<A: IVm>() {
    let empty_array: Any<A> = Array::default().to_any();
    check_eq::<A>("itself", empty_array.clone(), empty_array.clone(), true);
    // TODO: not yet
    // check_eq::<A>("skipped", Nullish::Null.to_any(), Nullish::Null.to_any(), true);
}

#[rustfmt::skip]
fn unary_plus<A: IVm>() {
    check_throws::<A>("bigint", Any::unary_plus(bigint_any(0)));
}

#[rustfmt::skip]
fn mul<A: IVm>() {
    check::<A>("oneByTwo", (1f64).to_any() * (2f64).to_any(), (2f64).to_any());
    check::<A>("oneByTwoSwapped", (2f64).to_any() * (1f64).to_any(), (2f64).to_any());
}

pub fn all<A: IVm>() {
    eq::<A>();
    unary_plus::<A>();
    mul::<A>();
}
`

export const proof = {
    path: () => {
        assertEq(directory, 'nanvm-lib/tests/test')
        assertEq(path, 'nanvm-lib/tests/test/generated.rs')
    },
    valueExpr: () => {
        assertEq(valueExpr(null), 'Nullish::Null.to_any()')
        assertEq(valueExpr(undefined), 'Nullish::Undefined.to_any()')
        assertEq(valueExpr(true), 'true.to_any()')
        assertEq(valueExpr(false), 'false.to_any()')
        assertEq(valueExpr(-0.3), '(-0.3f64).to_any()')
        assertEq(valueExpr('a'), 'string_any("a")')
        assertEq(valueExpr(-1n), 'bigint_any(-1)')
        assertEq(valueExpr([]), 'Array::default().to_any()')
        assertEq(valueExpr([null]), '[Nullish::Null.to_any()].to_array().to_any()')
        assertEq(valueExpr({}), 'Object::default().to_any()')
        assertEq(
            valueExpr({ k: null }),
            '[(string_key("k"), Nullish::Null.to_any())].to_object().to_any()')
        assertEq(valueExpr(functionValue), 'function_any()')
        assertEq(valueExpr(ref('stringArray')), 'string_array.clone()')
    },
    call: () => {
        assertEq(call('unaryPlus')(['x']), 'Any::unary_plus(x)')
        assertEq(call('unaryMinus')(['x']), '-(x)')
        assertEq(call('mul')(['x', 'y']), 'x * y')
        assertEq(call('stringCoercion')(['x']), 'x.to_string().map(|v| v.to_any())')
    },
    generate: () => {
        assertEq(generate(sample), expected)
    },
    generateData: () => {
        // The real corpus, which is what `ci-update` writes. Only its shape is
        // asserted here: its contents are checked by `cargo test`.
        const result = generate(data)
        assert(result.endsWith('}\n'), result)
        assert(result.includes('pub fn all<A: IVm>() {'), result)
        for (const g of data.groups) {
            assert(result.includes(`fn ${snakeCase(g.op)}<A: IVm>() {`), g.op)
            assert(result.includes(`${snakeCase(g.op)}::<A>();`), g.op)
        }
    },
    throw: {
        throwsIsNotAValue: () => valueExpr(throws),
    },
}
